<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,HttpException,RuntimeContext,Config};
final class ClientReportDeliveryService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly AlertNotificationService $notifications,private readonly ReportMailTransport $mail,private readonly Config $config) {}
    private function utc(?\DateTimeImmutable $now=null): \DateTimeImmutable {return ($now??new \DateTimeImmutable('now',new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('UTC'));}
    private function mapped(mixed $client): int {$id=$this->number($client);if(!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND client_id=:client AND user_id=:actor',['company'=>$this->company(),'client'=>$id,'actor'=>$this->actor()]))throw HttpException::notFound('Client access not found.');return $id;}
    public function preferences(): array {
        $rows=$this->db->fetchAll('SELECT a.client_id,s.schedule_id,s.time_zone,s.times_json,s.enabled,s.auto_share_approved,s.revision,s.next_due_at FROM client_portal_access a LEFT JOIN client_report_schedules s ON s.company_id=a.company_id AND s.client_id=a.client_id WHERE a.company_id=:company AND a.user_id=:actor ORDER BY a.client_id',['company'=>$this->company(),'actor'=>$this->actor()]);
        foreach($rows as&$r){$r['times']=$r['times_json']?json_decode($r['times_json'],true):ReportSchedule::DEFAULT_TIMES;$r['time_zone']=$r['time_zone']??'Africa/Johannesburg';$r['revision']=(int)($r['revision']??0);unset($r['times_json']);}unset($r);return ['preferences'=>$rows,'channels'=>['CLIENT_PORTAL','EMAIL'],'note'=>'Default delivery is midnight, 06:00, 12:00 and 18:00 in Africa/Johannesburg. Custom times use your selected time zone. Company approval is required before automatic aggregate reports are shared. SMTP acceptance does not confirm inbox delivery or reading.'];
    }
    public function schedules(): array {return $this->db->fetchAll('SELECT * FROM client_report_schedules WHERE company_id=:company ORDER BY schedule_id',['company'=>$this->company()]);}
    public function save(array $input,bool $manager=false,?\DateTimeImmutable $now=null): array {return $this->atomic(function()use($input,$manager,$now){
        $this->fields($input,$manager?['client_id','expected_revision','time_zone','times','enabled','auto_share_approved']:['client_id','expected_revision','time_zone','times','enabled']);$client=$manager?$this->row('clients','client_id',$input['client_id']??null)['client_id']:$this->mapped($input['client_id']??null);$times=ReportSchedule::times($input['times']??ReportSchedule::DEFAULT_TIMES);$zone=$input['time_zone']??'Africa/Johannesburg';ReportSchedule::zone($zone);if(!is_bool($input['enabled']??null)||($manager&&!is_bool($input['auto_share_approved']??null)))throw HttpException::unprocessable('Use boolean enabled and company approval values.');
        $old=$this->db->fetch('SELECT * FROM client_report_schedules WHERE company_id=:company AND client_id=:client',['company'=>$this->company(),'client'=>$client]);$revision=(int)($old['revision']??0);if($this->number($input['expected_revision']??null,0)!==$revision)throw HttpException::conflict('Report preferences changed. Refresh before saving.');$instant=$this->utc($now);$next=ReportSchedule::slot($instant,$zone,$times)->format('Y-m-d H:i:s');$approved=$manager?(int)$input['auto_share_approved']:(int)($old['auto_share_approved']??0);$params=['company'=>$this->company(),'client'=>$client,'zone'=>$zone,'times'=>json_encode($times,JSON_THROW_ON_ERROR),'enabled'=>(int)$input['enabled'],'approved'=>$approved,'revision'=>$revision+1,'next'=>$next,'actor'=>$this->actor(),'now'=>$instant->format('Y-m-d H:i:s')];
        // Keep a contiguous reporting boundary across preference changes. The new
        // next slot covers records since the last generated delivery, not a gap.
        if($old)$this->db->execute('UPDATE client_report_schedules SET time_zone=:zone,times_json=:times,enabled=:enabled,auto_share_approved=:approved,revision=:revision,next_due_at=:next,updated_by_user_id=:actor,updated_at=:now WHERE company_id=:company AND client_id=:client',$params);else $this->db->execute('INSERT INTO client_report_schedules(company_id,client_id,time_zone,times_json,enabled,auto_share_approved,revision,next_due_at,updated_by_user_id,updated_at) VALUES(:company,:client,:zone,:times,:enabled,:approved,:revision,:next,:actor,:now)',$params);$this->audit->record('client_report_schedule','preferences_saved',null,[],[],['client_id'=>$client,'revision'=>$revision+1,'manager'=>$manager]);return ['saved'=>true,'revision'=>$revision+1,'next_due_at'=>$next,'time_zone'=>$zone,'times'=>$times,'auto_share_approved'=>(bool)$approved];
    });}
    private function summary(array $site,string $from,string $to,string $generated): string {
        $keys=['company'=>$this->company(),'site'=>$site['site_id'],'start'=>$from,'end'=>$to];$patrols=$this->db->fetchAll("SELECT p.status,COUNT(*) AS total FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.started_at>=:start AND p.started_at<:end GROUP BY p.status",$keys);$counts=array_column($patrols,'total','status');
        $incidents=(int)$this->db->fetch('SELECT COUNT(*) AS total FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND occurred_at>=:start AND occurred_at<:end',$keys)['total'];
        $late=(int)$this->db->fetch("SELECT COUNT(*) AS total FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.status='COMPLETED' AND p.started_at<:before AND p.updated_at>=:received_start AND p.updated_at<:received_end",['company'=>$this->company(),'site'=>$site['site_id'],'before'=>$from,'received_start'=>$from,'received_end'=>$to])['total'];
        return 'Site: '.$site['site_name']."\nReporting period (UTC): $from to $to (end excluded)\nPatrols started in period, currently completed: ".($counts['COMPLETED']??0)."\nPatrols started in period, currently in progress: ".($counts['IN_PROGRESS']??0)."\nEarlier-started patrols updated as completed in this period (including late offline uploads): $late\nIncident records captured in this period: $incidents\nSnapshot generated (UTC): $generated\nThis aggregate includes records received by generation time. Offline patrols may arrive later; counts are not independent proof of physical attendance or arrival. Incident details and evidence are excluded.";
    }
    public function generate(?\DateTimeImmutable $now=null): array {return $this->atomic(function()use($now){
        $instant=$this->utc($now);$generated=$instant->format('Y-m-d H:i:s');$made=0;
        while($made<20){$schedule=$this->db->fetch('SELECT * FROM client_report_schedules WHERE company_id=:company AND enabled=1 AND auto_share_approved=1 AND next_due_at<=:now ORDER BY next_due_at,schedule_id LIMIT 1',['company'=>$this->company(),'now'=>$generated]);if(!$schedule)break;$slot=new \DateTimeImmutable($schedule['next_due_at'],new \DateTimeZone('UTC'));$times=json_decode($schedule['times_json'],true,512,JSON_THROW_ON_ERROR);$from=$schedule['last_due_at']??ReportSchedule::slot($slot,$schedule['time_zone'],$times,true)->format('Y-m-d H:i:s');$to=$slot->format('Y-m-d H:i:s');$next=ReportSchedule::slot($slot,$schedule['time_zone'],$times)->format('Y-m-d H:i:s');
            $old=$this->db->fetch('SELECT run_id FROM client_report_runs WHERE company_id=:company AND schedule_id=:schedule AND slot_at=:slot',['company'=>$this->company(),'schedule'=>$schedule['schedule_id'],'slot'=>$to]);if(!$old){
                $sites=$this->db->fetchAll('SELECT site_id,site_name FROM sites WHERE company_id=:company AND client_id=:client AND deleted_at IS NULL ORDER BY site_id LIMIT 501',['company'=>$this->company(),'client'=>$schedule['client_id']]);if(count($sites)>500)throw HttpException::unprocessable('More than 500 sites for a scheduled client report.');$ids=[];$sections=[];$local=$slot->setTimezone(ReportSchedule::zone($schedule['time_zone']))->format('Y-m-d H:i T');$title='Scheduled service summary: '.$local;
                foreach($sites as$site){$text=$this->summary($site,$from,$to,$generated);$sections[]=$text;$this->db->execute('INSERT INTO published_site_reports(company_id,client_id,site_id,title,report_text,published_by_user_id,published_at) VALUES(:company,:client,:site,:title,:text,:actor,:now)',['company'=>$this->company(),'client'=>$schedule['client_id'],'site'=>$site['site_id'],'title'=>$title,'text'=>$text,'actor'=>$this->actor(),'now'=>$generated]);$ids[]=(int)$this->db->connection()->lastInsertId();}
                $body=implode("\n\n----------------\n\n",$sections);if(!$sites)$body="No active sites were mapped to this client when the report was generated.\nPeriod (UTC): $from to $to";$portal=(string)$this->config->get('report_mail.portal_url','');if(str_starts_with($portal,'https://'))$body.="\n\nClient portal (sign-in required): ".$portal;$this->db->execute('INSERT INTO client_report_runs(company_id,schedule_id,client_id,slot_at,period_from,period_to,generated_at,portal_report_ids,email_subject,email_body) VALUES(:company,:schedule,:client,:slot,:start,:end,:now,:ids,:subject,:body)',['company'=>$this->company(),'schedule'=>$schedule['schedule_id'],'client'=>$schedule['client_id'],'slot'=>$to,'start'=>$from,'end'=>$to,'now'=>$generated,'ids'=>json_encode($ids,JSON_THROW_ON_ERROR),'subject'=>$title,'body'=>$body]);$run=(string)$this->db->connection()->lastInsertId();
                $users=$this->db->fetchAll("SELECT u.user_id,u.email FROM users u JOIN client_portal_access a ON a.company_id=u.company_id AND a.user_id=u.user_id WHERE a.company_id=:company AND a.client_id=:client AND u.status='ACTIVE' ORDER BY u.user_id LIMIT 101",['company'=>$this->company(),'client'=>$schedule['client_id']]);if(count($users)>100)throw HttpException::unprocessable('More than 100 mapped recipients for a client schedule.');foreach($users as$user){$valid=filter_var($user['email'],FILTER_VALIDATE_EMAIL)!==false;$this->db->execute('INSERT INTO client_report_outbox(company_id,run_id,recipient_user_id,recipient_email,state,status_message) VALUES(:company,:run,:user,:email,:state,:message)',['company'=>$this->company(),'run'=>$run,'user'=>$user['user_id'],'email'=>(string)$user['email'],'state'=>$valid?'PENDING':'FAILED','message'=>$valid?'Awaiting mail worker.':'Recipient email is invalid.']);$this->notifications->createNotification(['recipient_user_id'=>$user['user_id'],'event_type'=>'CLIENT_REPORT_READY','severity'=>'LOW','title'=>'Scheduled client report ready','message'=>$title.'. Sign in to the client portal for the report.','channel'=>'IN_APP']);}$this->audit->record('client_report_run','generated',$run,[],[],['schedule_id'=>$schedule['schedule_id'],'slot'=>$to,'portal_reports'=>count($ids),'email_recipients'=>count($users)]);
            }
            $this->db->execute('UPDATE client_report_schedules SET last_due_at=:slot,next_due_at=:next WHERE company_id=:company AND schedule_id=:schedule',['slot'=>$to,'next'=>$next,'company'=>$this->company(),'schedule'=>$schedule['schedule_id']]);$made++;
        }return ['periods_generated'=>$made,'generated_at'=>$generated,'batch_limit'=>20];
    });}
    private function recipientValid(array $delivery): bool {return (bool)$this->db->fetch("SELECT u.user_id FROM users u JOIN client_portal_access a ON a.company_id=u.company_id AND a.user_id=u.user_id JOIN client_report_runs r ON r.company_id=a.company_id AND r.client_id=a.client_id JOIN client_report_schedules s ON s.company_id=r.company_id AND s.schedule_id=r.schedule_id AND s.enabled=1 AND s.auto_share_approved=1 WHERE u.company_id=:company AND u.user_id=:user AND u.status='ACTIVE' AND u.email=:email AND r.run_id=:run",['company'=>$this->company(),'user'=>$delivery['recipient_user_id'],'email'=>$delivery['recipient_email'],'run'=>$delivery['run_id']]);}
    public function sendPending(): array {
        if($this->db->inTransaction())throw new \LogicException('SMTP delivery must run outside a transaction.');$accepted=0;$uncertain=0;
        $this->atomic(function(){ $this->db->execute("UPDATE client_report_outbox SET state='UNCERTAIN',status_message='A previous worker stopped during delivery. Review before retrying; email may have been accepted.' WHERE company_id=:company AND state='SENDING' AND attempted_at<:old",['company'=>$this->company(),'old'=>gmdate('Y-m-d H:i:s',time()-300)]);return [];});
        for($i=0;$i<20;$i++){$job=$this->atomic(function(){
            $job=$this->db->fetch("SELECT d.*,r.email_subject,r.email_body FROM client_report_outbox d JOIN client_report_runs r ON r.company_id=d.company_id AND r.run_id=d.run_id WHERE d.company_id=:company AND d.state IN ('PENDING','WAITING_CONFIG') ORDER BY d.delivery_id LIMIT 1",['company'=>$this->company()]);if(!$job)return [];
            if(!$this->recipientValid($job)){$this->db->execute("UPDATE client_report_outbox SET state='CANCELLED',status_message='Client mapping, active account or email address changed.' WHERE company_id=:company AND delivery_id=:id",['company'=>$this->company(),'id'=>$job['delivery_id']]);return ['cancelled'=>true];}
            if(!$this->mail->configured()){$this->db->execute("UPDATE client_report_outbox SET state='WAITING_CONFIG',status_message='SMTP is not configured. Portal report remains available.' WHERE company_id=:company AND delivery_id=:id",['company'=>$this->company(),'id'=>$job['delivery_id']]);return ['waiting'=>true];}
            $this->db->execute("UPDATE client_report_outbox SET state='SENDING',attempts=attempts+1,attempted_at=:now,status_message='Mail attempt started.' WHERE company_id=:company AND delivery_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$job['delivery_id']]);return $job;
        });if(!$job||isset($job['waiting']))break;if(isset($job['cancelled']))continue;
            try{$this->mail->send($job['recipient_email'],$job['email_subject'],$job['email_body'],$this->company().':'.$job['delivery_id']);$state='ACCEPTED';$message='Accepted by SMTP server; inbox delivery and reading are not confirmed.';$accepted++;}catch(\Throwable){$state='UNCERTAIN';$message='Mail attempt failed or its outcome is uncertain. Review before retrying to avoid duplicate email.';$uncertain++;}
            $this->atomic(function()use($job,$state,$message){$this->db->execute('UPDATE client_report_outbox SET state=:state,status_message=:message,accepted_at=:accepted WHERE company_id=:company AND delivery_id=:id',['state'=>$state,'message'=>$message,'accepted'=>$state==='ACCEPTED'?gmdate('Y-m-d H:i:s'):null,'company'=>$this->company(),'id'=>$job['delivery_id']]);$this->audit->record('client_report_delivery',strtolower($state),(string)$job['delivery_id']);return [];});
        }return ['smtp_accepted'=>$accepted,'uncertain'=>$uncertain,'smtp_configured'=>$this->mail->configured()];
    }
    public function history(bool $self=false): array {
        return $this->db->fetchAll('SELECT d.delivery_id,d.run_id,d.recipient_user_id,d.state,d.attempts,d.attempted_at,d.accepted_at,d.status_message,r.slot_at,r.period_from,r.period_to FROM client_report_outbox d JOIN client_report_runs r ON r.company_id=d.company_id AND r.run_id=d.run_id WHERE d.company_id=:company'.($self?' AND d.recipient_user_id=:actor':'').' ORDER BY d.delivery_id DESC LIMIT 500',$self?['company'=>$this->company(),'actor'=>$this->actor()]:['company'=>$this->company()]);
    }
    public function retry(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['reason']);$reason=$this->text($input['reason']??null);if(mb_strlen($reason)<10)throw HttpException::unprocessable('Record a review reason of at least 10 characters.');$job=$this->row('client_report_outbox','delivery_id',$id);if(!in_array($job['state'],['UNCERTAIN','FAILED','WAITING_CONFIG','CANCELLED'],true))throw HttpException::conflict('This delivery is not eligible for a reviewed retry.');$user=$this->row('users','user_id',$job['recipient_user_id']);$job['recipient_email']=$user['email'];if(!$this->recipientValid($job)||!filter_var($user['email'],FILTER_VALIDATE_EMAIL))throw HttpException::conflict('Recipient must have current client access and a valid email.');$this->db->execute("UPDATE client_report_outbox SET state='PENDING',recipient_email=:email,status_message='Operator reviewed and queued a retry.' WHERE company_id=:company AND delivery_id=:id",['email'=>$user['email'],'company'=>$this->company(),'id'=>$id]);$this->audit->record('client_report_delivery','retry_reviewed',$id,[],[],['reason'=>$reason]);return ['queued'=>true,'note'=>'A prior uncertain attempt may already have been delivered.'];});}
}
